changeSet.sql:
CREATE SCHEMA IF NOT EXISTS platform;
CREATE TABLE IF NOT EXISTS platform.tenant (
    tenant_id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    active BOOLEAN DEFAULT true NOT NULL,
    version INT DEFAULT 1 NOT NULL
);
CREATE TABLE IF NOT EXISTS platform.subject (
    subject_id SERIAL PRIMARY KEY,
    display_name VARCHAR(255) NOT NULL
);

INSERT INTO platform.tenant (name)
VALUES ('QTO First Tenant');
INSERT INTO company (company_name, company_type, company_uuid, tenant_id)
VALUES ('QTO First Tenant', 'Vertek Client', 'QTO First Tenant',
        (SELECT tenant.tenant_id FROM platform.tenant WHERE name = 'QTO First Tenant'));

INSERT INTO platform.tenant (name)
VALUES ('Endeavor');
