VALUES ('Endeavor', 'Vertek Client', 'Endeavor',
        (SELECT tenant.tenant_id FROM platform.tenant WHERE name = 'Endeavor'));

INSERT INTO platform.tenant (name)
VALUES ('Demo Tenant');
INSERT INTO company (company_name, company_type, company_uuid, tenant_id)
VALUES ('Demo Tenant', 'Vertek Client', 'Demo Tenant',
        (SELECT tenant.tenant_id FROM platform.tenant WHERE name = 'Demo Tenant'));

UPDATE location_milestone_instance lmi SET milestone_id = (SELECT milestone_id FROM milestone_instance mi WHERE lmi.milestone_instance_id = mi.milestone_instance_id);
UPDATE service_milestone_instance smi SET milestone_id = (SELECT milestone_id FROM milestone_instance mi WHERE smi.milestone_instance_id = mi.milestone_instance_id);
DELETE lmi1 FROM location_milestone_instance lmi1, location_milestone_instance lmi2 WHERE lmi1.milestone_instance_id > lmi2.milestone_instance_id AND lmi1.location_id = lmi2.location_id AND lmi1.milestone_id = lmi2.milestone_id;
DELETE smi1 FROM service_milestone_instance smi1, service_milestone_instance smi2 WHERE smi1.milestone_instance_id > smi2.milestone_instance_id AND smi1.service_id = smi2.service_id AND smi1.milestone_id = smi2.milestone_id;
DELETE ii, sii FROM interval_instance ii JOIN service_interval_instance sii ON ii.interval_instance_id = sii.interval_instance_id
       WHERE ii.open_milestone_instance_id NOT IN (SELECT milestone_instance_id FROM location_milestone_instance UNION SELECT milestone_instance_id FROM service_milestone_instance)
          OR ii.close_milestone_instance_id NOT IN (SELECT milestone_instance_id FROM location_milestone_instance UNION SELECT milestone_instance_id FROM service_milestone_instance);
DELETE FROM milestone_instance WHERE milestone_instance_id NOT IN (SELECT milestone_instance_id FROM location_milestone_instance UNION SELECT milestone_instance_id FROM service_milestone_instance UNION SELECT milestone_instance_id FROM order_milestone_instance);

INSERT INTO milestone (milestone_name, milestone_code) VALUES ('Site Access Confirmed', 'SITE_ACCESS_CONFIRMED');

INSERT INTO milestone_display_set_include (milestone_display_set_id, milestone_id, milestone_active, milestone_sequence,
                                           milestone_required, adjustable, workflow_driven, has_time, disallow_future)
VALUES (@displaySetId, (SELECT milestone_id FROM milestone WHERE milestone_code = 'SITE_ACCESS_CONFIRMED'), 1, 1065, 1, 1, 0, 0, 0);

INSERT INTO milestone_display_set_include (milestone_display_set_id, milestone_id, milestone_active, milestone_sequence,
                                           milestone_required, adjustable, workflow_driven, has_time, disallow_future)
VALUES (@displaySetId, (SELECT milestone_id FROM milestone WHERE milestone_code = 'SITE_ACCESS_CONFIRMED'), 1, 1065, 1, 1, 0, 0, 0);

INSERT INTO lookup_type (lookup_type_descr, lookup_type_code, lookup_type_active, modifiable, sort_strategy)
VALUES ('Service Owner', 'SERVICE_OWNER', true, true, true);

INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, sort_seq, lookup_value_active)
VALUES ((SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'SERVICE_OWNER'), 'Endeavor', 'Endeavor', 10, true),
       ((SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'SERVICE_OWNER'), 'Customer', 'Customer', 20, true);

INSERT INTO tenant_lookup_value (lookup_value_id, tenant_id)
SELECT lookup_value_id, (select tenant_id from v_tenant where name = 'QTO First Tenant')
FROM lookup_value
WHERE lookup_type_id = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'SERVICE_OWNER');

INSERT INTO tenant_lookup_value (lookup_value_id, tenant_id)
SELECT lookup_value_id, (select tenant_id from v_tenant where name = 'Demo Tenant')
FROM lookup_value
WHERE lookup_type_id = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'SERVICE_OWNER');

